test('invoiceTotals does not mutate input', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 8500, vatRate: 21 }],
  };
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  invoiceTotals(invoice);

  assert.deepEqual(invoice, invoiceCopy);
});

// Bulk discount tests (2.5% off for 10+ units)
test('invoiceTotals with bulk discount for exactly 10 units', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, vatRate: 21 }],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // 10 * 8500 = 85000
  // Bulk discount (2.5%): 85000 * 2.5% = 2125
  // Amount after discount: 85000 - 2125 = 82875
  // VAT (21%): 82875 * 21% = 17403.75 -> 17404
  // Total: 82875 + 17404 = 100279
  assert.equal(r.value.subtotal, 85000);
  assert.equal(r.value.discount, 2125);
  assert.equal(r.value.vat, 17404);
  assert.equal(r.value.total, 100279);
});

test('invoiceTotals with no bulk discount for 9 units', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 8500, vatRate: 21 }],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // 9 * 8500 = 76500
  // No bulk discount (only 9 units)
  // VAT (21%): 76500 * 21% = 16065
  // Total: 76500 + 16065 = 92565
  assert.equal(r.value.subtotal, 76500);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 16065);
  assert.equal(r.value.total, 92565);
});

test('invoiceTotals with bulk discount for 20 units', () => {
  const invoice = {
    lines: [{ qty: 20, unitPrice: 8500, vatRate: 21 }],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // 20 * 8500 = 170000
  // Bulk discount (2.5%): 170000 * 2.5% = 4250
  // Amount after discount: 170000 - 4250 = 165750
  // VAT (21%): 165750 * 21% = 34807.5 -> 34808
  // Total: 165750 + 34808 = 200558
  assert.equal(r.value.subtotal, 170000);
  assert.equal(r.value.discount, 4250);
  assert.equal(r.value.vat, 34808);
  assert.equal(r.value.total, 200558);
});

test('invoiceTotals with bulk discount and line discount combined', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 10, vatRate: 21 }],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // 10 * 8500 = 85000
  // Line discount (10%): 85000 * 10% = 8500
  // Amount after line discount: 85000 - 8500 = 76500
  // Bulk discount (2.5%): 76500 * 2.5% = 1912.5 -> 1913 (rounded)
  // Amount after both discounts: 76500 - 1913 = 74587
  // Total discount: 8500 + 1913 = 10413
  // VAT (21%): 74587 * 21% = 15663.27 -> 15663
  // Total: 85000 - 10413 + 15663 = 90250
  assert.equal(r.value.subtotal, 85000);
  assert.equal(r.value.discount, 10413);
  assert.equal(r.value.vat, 15663);
  assert.equal(r.value.total, 90250);
});

test('invoiceTotals with bulk discount and 0% line discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // Line discount (0%) doesn't apply
  // Bulk discount still applies: 85000 * 2.5% = 2125
  // Amount after bulk discount: 85000 - 2125 = 82875
  // VAT: 82875 * 21% = 17403.75 -> 17404
  // Total: 85000 - 2125 + 17404 = 100279
  assert.equal(r.value.subtotal, 85000);
  assert.equal(r.value.discount, 2125);
  assert.equal(r.value.vat, 17404);
  assert.equal(r.value.total, 100279);
});

test('invoiceTotals with multiple lines: some with bulk discount, some without', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, vatRate: 21 },
      { qty: 5, unitPrice: 9500, vatRate: 21 },
    ],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // Line 1: 10 * 8500 = 85000, bulk discount: 2125, after: 82875, VAT: 17404
  // Line 2: 5 * 9500 = 47500, no bulk discount, VAT: 47500 * 21% = 9975
  // Subtotal: 132500
  // Discount: 2125
  // VAT: 27379
  // Total: 132500 - 2125 + 27379 = 157754
  assert.equal(r.value.subtotal, 132500);
  assert.equal(r.value.discount, 2125);
  assert.equal(r.value.vat, 27379);
  assert.equal(r.value.total, 157754);
});

test('invoiceTotals with multiple lines all with bulk discount', () => {
