  assert.equal(r.ok, true);
  // Line 1: 10 * 8500 = 85000, bulk discount: 2125, after: 82875, VAT: 17404
  // Line 2: 15 * 9500 = 142500, bulk discount: 3562.5 -> 3563, after: 138937, VAT: 29177
  // Subtotal: 227500
  // Discount: 5688
  // VAT: 46581
  // Total: 227500 - 5688 + 46581 = 268393
  assert.equal(r.value.subtotal, 227500);
  assert.equal(r.value.discount, 5688);
  assert.equal(r.value.vat, 46581);
  assert.equal(r.value.total, 268393);
});

test('invoiceTotals bulk discount with VAT-exempt items', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 60000, vatRate: 0 }],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // 10 * 60000 = 600000
  // Bulk discount (2.5%): 600000 * 2.5% = 15000
  // After discount: 600000 - 15000 = 585000
  // VAT (0%): 0
  // Total: 585000
