test('invoiceTotals bulk discount with mixed VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, vatRate: 21 },
      { qty: 20, unitPrice: 37, vatRate: 9 },
    ],
