  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // Line 1: 10 * 8500 = 85000, bulk discount: 2125, after: 82875, VAT: 17404
  // Line 2: 20 * 37 = 740, bulk discount: 18.5 -> 19, after: 721, VAT: 64
  // Subtotal: 85740
  // Discount: 2144
  // VAT: 17468
  // Total: 85740 - 2144 + 17468 = 101064
  assert.equal(r.value.subtotal, 85740);
  assert.equal(r.value.discount, 2144);
  assert.equal(r.value.vat, 17468);
  assert.equal(r.value.total, 101064);
