test('invoiceTotals bulk discount with voucher', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, vatRate: 21 }],
    voucher: { code: 'SAVE10', amount: 5000 },
  };

  const r = invoiceTotals(invoice);
