  assert.equal(r.value.total, 117975);
});

test('invoiceTotals bulk discount with small line discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 2, vatRate: 21 }],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // 10 * 8500 = 85000
  // Line discount (2%): 85000 * 2% = 1700
  // After line discount: 85000 - 1700 = 83300
  // Bulk discount (2.5%): 83300 * 2.5% = 2082.5 -> 2083
  // After both: 83300 - 2083 = 81217
  // Total discount: 1700 + 2083 = 3783
  // VAT: 81217 * 21% = 17055.57 -> 17056
  // Total: 85000 - 3783 + 17056 = 98273
  assert.equal(r.value.discount, 3783);
  assert.equal(r.value.total, 98273);
});

test('invoiceTotals bulk discount with large line discount', () => {
