    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 20, vatRate: 21 }],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // 10 * 8500 = 85000
  // Line discount (20%): 85000 * 20% = 17000
  // After line discount: 85000 - 17000 = 68000
  // Bulk discount (2.5%): 68000 * 2.5% = 1700
  // After both: 68000 - 1700 = 66300
  // Total discount: 17000 + 1700 = 18700
  // VAT: 66300 * 21% = 13923
  // Total: 85000 - 18700 + 13923 = 80223
  assert.equal(r.value.discount, 18700);
  assert.equal(r.value.total, 80223);
});

test('invoiceTotals bulk discount with many units', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, vatRate: 21 }],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // 100 * 1000 = 100000
  // Bulk discount (2.5%): 100000 * 2.5% = 2500
  // After discount: 100000 - 2500 = 97500
  // VAT: 97500 * 21% = 20475
