  assert.equal(r.value.subtotal, 100000);
  assert.equal(r.value.discount, 2500);
  assert.equal(r.value.vat, 20475);
  assert.equal(r.value.total, 117975);
});

test('invoiceTotals bulk discount on multiple items with same bulk status', () => {
  const invoice = {
    lines: [
      { qty: 12, unitPrice: 5000, vatRate: 21 },
      { qty: 11, unitPrice: 6000, vatRate: 21 },
      { qty: 13, unitPrice: 7000, vatRate: 21 },
    ],
  };

  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  // Line 1: 12 * 5000 = 60000, bulk discount: 1500, after: 58500, VAT: 12285
