test('invoiceTotals bulk discount calculation order is correct', () => {
  // Verify that bulk discount is applied AFTER line discount, not before
  const invoiceA = {
    lines: [{ qty: 10, unitPrice: 10000, discountPercent: 10, vatRate: 0 }],
  };
  const invoiceB = {
    lines: [{ qty: 10, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
  };

  const rA = invoiceTotals(invoiceA);
  const rB = invoiceTotals(invoiceB);

  // Discount on A should be: line discount (10000) + bulk on remainder (2250) = 12250
  // Discount on B should be: just bulk (2500)
  assert.equal(rA.value.discount, 12250);
  assert.equal(rB.value.discount, 2500);
  // Total on A should be: 100000 - 12250 = 87750
  // Total on B should be: 100000 - 2500 = 97500
  assert.equal(rA.value.total, 87750);
  assert.equal(rB.value.total, 97500);
});

