  assert.equal(Number.isInteger(fee), true);
});

test('lateFee with 0 days overdue', () => {
  const invoice = {
    status: 'issued',
    dueDate: '2026-11-06',
    lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
  };

  const fee = lateFee(invoice, '2026-11-06');
  assert.equal(fee, 0);
});

test('lateFee with negative days overdue (future due date)', () => {
  const invoice = {
    status: 'issued',
    dueDate: '2026-11-30',
    lines: [{ qty: 1, unitPrice: 10000, vatRate: 0 }],
  };

  const fee = lateFee(invoice, '2026-11-06');
  assert.equal(fee, 0);
});

test('lateFee with voucher', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // 17000 + 3570 = 20570, with voucher: 20570 - 1000 = 19570
  const withVoucher = {
    ...issued,
    voucher: { code: 'DISCOUNT', amount: 1000 },
  };

  // NET30 from 2026-10-01 = due 2026-10-31
  // Fee on 2026-11-10 (10 days overdue) = 19570 * (10 * 0.04 / 100) = 19570 * 0.004 = 78.28 -> 78
  const fee = lateFee(withVoucher, '2026-11-10');

  assert.equal(fee, 78);
});

test('lateFee with VAT-exempt item', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // 60000, no VAT
  // NET30 from 2026-10-01 = due 2026-10-31
  // Fee on 2026-11-15 (15 days overdue) = 60000 * (15 * 0.04 / 100) = 60000 * 0.006 = 360
  const fee = lateFee(issued, '2026-11-15');

  assert.equal(fee, 360);
});

test('lateFee does not mutate invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const invoiceCopy = JSON.parse(JSON.stringify(issued));

  lateFee(issued, '2026-11-15');

  assert.deepEqual(issued, invoiceCopy);
});

test('lateFee with month boundary', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // C-001 gold tier: 9771
  // NET30 from 2026-09-01 = due 2026-10-01
  // Fee on 2026-10-31 (30 days overdue) = 9771 * (30 * 0.04 / 100) = 9771 * 0.012 = 117.252 -> 117
  const fee = lateFee(issued, '2026-10-31');

  assert.equal(fee, 117);
});

test('lateFee with year boundary', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // C-001 gold tier: 9771
  // NET30 from 2025-12-01 = due 2025-12-31
  // Fee on 2026-01-31 (31 days overdue) = 9771 * (31 * 0.04 / 100) = 9771 * 0.0124 = 121.16 -> 121
  const fee = lateFee(issued, '2026-01-31');

  assert.equal(fee, 121);
});

test('lateFee rounding uses banker\'s rounding', () => {
  const invoice = {
    status: 'issued',
    dueDate: '2026-11-06',
    lines: [{ qty: 1, unitPrice: 12500, vatRate: 0 }],
  };

  // Due = 12500
  // 1 day overdue: 12500 * 0.04% = 5.0 -> 5
  // 3 days overdue: 12500 * 0.12% = 15.0 -> 15
  assert.equal(lateFee(invoice, '2026-11-07'), 5);
  assert.equal(lateFee(invoice, '2026-11-09'), 15);
});

